// Person → project mapping (Program A vs Program B)
// Reporter C is on Program B. Everyone else is on Program A.
const PROGRAM_B_ASSIGNEES = new Set([
  'reporter c'
]);

// Status → true owner (for the owner tracker which is assigned to Reporter B)
// REPORTER D PROJECT TRACKER tickets are owned by Reporter D (the reporter),
// not the assignee (Reporter B who manages them).
const OWNER_TRACKER_STATUS = 'reporter d project tracker';

const res = items[0].json || {};
const issues = res.issues || [];

const out = [];
for (const issue of issues) {
  const f = issue.fields || {};
  const statusName = (f.status?.name || '').toLowerCase();
  const assigneeName = (f.assignee?.displayName || '').toLowerCase();

  // Determine true reporter
  let reporter;
  if (statusName === OWNER_TRACKER_STATUS) {
    // Reporter D's tracker: reporter field = Reporter D (ticket creator = the worker)
    reporter = f.reporter?.displayName || 'Reporter D';
  } else {
    reporter = f.assignee?.displayName || null;
  }

  if (!reporter) continue; // skip unassigned tickets entirely

  // Skip Project Manager as reporter
  if (reporter.toLowerCase().includes('project manager')) continue;

  // Determine program line
  const isProgramB = PROGRAM_B_ASSIGNEES.has(assigneeName);
  const programLine = isProgramB
    ? 'Program: Program B Operations & Maintenance Support'
    : 'Program: Program A Operations & Maintenance Support';

  out.push({
    json: {
      // Pass the full issue fields through — no second API call needed
      issueKey: issue.key,
      summary: f.summary || '',
      status: f.status?.name || '',
      reporter: reporter,
      programLine: programLine,
      fields: f,
      changelog: issue.changelog || {}
    }
  });
}

console.log(`[Flatten] ${issues.length} issues → ${out.length} valid items`);
return out;

// Pass-through: full issue data already included from Flatten Issue List.
// No second API call needed. Runs once for all items.
return items;

// Keep only tickets that have at least one comment from THIS week.
// "This week" = Mon 00:00 → Fri 23:59 America/New_York.
// Tickets with zero this-week comments are silently skipped.

const EST_OFFSET_MS = 5 * 60 * 60 * 1000; // UTC-5 (EST; close enough for weekly cadence)

function toESTMidnightUTC(utcMs) {
  const estMs = utcMs - EST_OFFSET_MS;
  const midnight = estMs - (estMs % 86400000);
  return midnight + EST_OFFSET_MS;
}

const nowUTC = Date.now();
const estDow = new Date(nowUTC - EST_OFFSET_MS).getUTCDay(); // 0=Sun
const daysToMonday = estDow === 0 ? -6 : 1 - estDow;

const mondayUTC = toESTMidnightUTC(nowUTC) + daysToMonday * 86400000;
const fridayUTC  = mondayUTC + 4 * 86400000 + 23 * 3600000 + 59 * 60000 + 59999;

function isThisWeek(dateStr) {
  if (!dateStr) return false;
  const ms = new Date(dateStr).getTime();
  return ms >= mondayUTC && ms <= fridayUTC;
}

// Extract plain text from ADF comment body
function adfToText(body) {
  if (!body) return '';
  if (typeof body === 'string') return body;
  const parts = [];
  function walk(node) {
    if (!node) return;
    if (node.type === 'text') parts.push(node.text || '');
    if (node.type === 'date') {
      // Convert timestamp to readable date
      const ts = node.attrs?.timestamp;
      if (ts) parts.push(new Date(parseInt(ts)).toISOString().split('T')[0]);
    }
    (node.content || []).forEach(walk);
  }
  walk(body);
  return parts.join(' ').replace(/\s+/g, ' ').trim();
}

const filtered = [];

for (const item of items) {
  const f = item.json.fields || {};
  const comments = (f.comment?.comments || []);

  // Find comments from this week
  const thisWeekComments = comments.filter(c =>
    isThisWeek(c.created) || isThisWeek(c.updated)
  );

  if (thisWeekComments.length === 0) {
    console.log(`[Filter] SKIP ${item.json.issueKey} — no this-week comments`);
    continue;
  }

  // Attach extracted this-week comment texts for the AI
  const thisWeekTexts = thisWeekComments.map(c => ({
    author: c.author?.displayName || 'Unknown',
    date: (c.created || '').split('T')[0],
    text: adfToText(c.body)
  }));

  // Also extract custom field values (structured report fields)
  const customFields = {};
  for (let i = 290; i <= 299; i++) {
    const key = `customfield_1${i}`;
    const val = f[key];
    if (val && typeof val === 'string' && val.trim()) {
      customFields[key] = val.trim();
    } else if (val && typeof val === 'object') {
      const text = adfToText(val);
      if (text) customFields[key] = text;
    }
  }

  filtered.push({
    json: {
      ...item.json,
      thisWeekComments: thisWeekTexts,
      customFields: customFields,
      totalComments: comments.length
    }
  });
}

console.log(`[Filter] ${items.length} tracker tickets → ${filtered.length} with this-week activity`);
return filtered;

// Build Boss Summary from filtered Jira activity items
const clean = (s) => String(s ?? '').trim();

function getReporterName(item) {
  const f = item.json?.fields || item.json || {};
  return (
    clean(f.reporter?.displayName) ||
    clean(f.reporter?.name) ||
    clean(f.updateAuthor?.displayName) ||
    clean(f.author?.displayName) ||
    clean(item.json?.reporter) ||
    'Unknown'
  );
}

const counts = new Map();
for (const it of items) {
  const name = getReporterName(it);
  counts.set(name, (counts.get(name) || 0) + 1);
}

const sorted = [...counts.entries()]
  .filter(([name]) => name !== 'Unknown')
  .sort((a,b) => b[1] - a[1]);

const lines = sorted.length
  ? sorted.map(([name, n]) => `• ${name} — ${n} item(s)`).join('\n')
  : 'No activity found for this week (per filter).';

const subject = `Weekly Tracker Update — ${sorted.length} active team member(s)`;
const body = `Hi manager,\n\nHere's who logged activity on their board tracker this week:\n\n${lines}\n\n— Automated Jira → Weekly Report workflow`.trim();

return [{ json: { subject, body, activeCount: sorted.length, activeMembers: sorted.map(([n]) => n) } }];

const EXCLUDED = new Set(['project manager', 'n/a', '', 'unknown']);

const FIELDS = [
  'activitiesPerformed','tasksAccomplished','issuesChallenges',
  'risksVulnerabilities','processImprovementOpportunities',
  'supportNeeds','upcomingWeekActivities','plannedLeave'
];

function weekEndingNY() {
  const TZ = 'America/New_York';
  const nowNY = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));
  const dow = nowNY.getDay();
  const toFri = dow === 0 ? -2 : (5 - dow + 7) % 7 || 0;
  const fri = new Date(nowNY);
  fri.setDate(nowNY.getDate() + toFri);
  return [fri.getFullYear(),
          String(fri.getMonth()+1).padStart(2,'0'),
          String(fri.getDate()).padStart(2,'0')].join('-');
}
const WEEK_ENDING = weekEndingNY();

function parseJSON(raw) {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
  let s = typeof raw === 'string' ? raw : '';
  s = s.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
  try { return JSON.parse(s); } catch {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) try { return JSON.parse(m[0]); } catch {}
  return {};
}

function splitBullets(text) {
  if (!text || String(text).trim().toLowerCase() === 'n/a') return [];
  return String(text)
    .replace(/\r/g, '')
    // Split on newlines AND inline bullet chars
    .split(/\n|(?<=\S)\s*[•·\u2022]\s*/)
    .map(l => l.replace(/^[\s•·\u2022\-\*,]+/, '').trim())
    .filter(l => l && l.toLowerCase() !== 'n/a');
}

// Strip the "TicketArea: " prefix for comparison purposes only
function stripPrefix(s) {
  return s.replace(/^[A-Z][A-Za-z0-9 &\-\/]+:\s*/, '').toLowerCase().trim();
}

const STOPWORDS = new Set('a an the and or but in on at to for of with is are was were be been have has had do does did will would could should may might this that these those it its by from as'.split(' '));

function sigWords(s) {
  return new Set(
    stripPrefix(s)
      .replace(/[^a-z0-9 ]/g,' ')
      .split(/\s+/)
      .filter(w => w.length > 2 && !STOPWORDS.has(w))
  );
}

function overlap(a, b) {
  const wa = sigWords(a), wb = sigWords(b);
  if (!wa.size || !wb.size) return 0;
  let shared = 0;
  for (const w of wa) if (wb.has(w)) shared++;
  return shared / Math.min(wa.size, wb.size);
}

function dedup(bullets) {
  const result = [];
  for (const b of bullets) {
    let isDupe = false;
    for (let i = 0; i < result.length; i++) {
      if (result[i].toLowerCase() === b.toLowerCase()) { isDupe = true; break; }
      if (overlap(b, result[i]) >= 0.65) {
        // Keep the longer (more informative) bullet
        if (b.length > result[i].length) result[i] = b;
        isDupe = true; break;
      }
    }
    if (!isDupe) result.push(b);
  }
  return result;
}

const groups = new Map();

for (const item of items) {
  const src = parseJSON(item.json?.output !== undefined ? item.json.output : item.json);
  const reporter = (src.reporter || '').trim();
  if (!reporter || EXCLUDED.has(reporter.toLowerCase())) continue;

  const key = reporter.toLowerCase();
  if (!groups.has(key)) {
    groups.set(key, {
      reporter,
      reportTitle: src.reportTitle || 'Weekly Activity Report',
      programLine: src.programLine || 'Program: Operations & Maintenance Support',
      bullets: Object.fromEntries(FIELDS.map(f => [f, []]))
    });
  }

  const g = groups.get(key);
  if (src.programLine && !src.programLine.includes('Program B Operations')) {
    g.programLine = src.programLine;
  }

  for (const f of FIELDS) {
    const bullets = splitBullets(src[f]);
    g.bullets[f].push(...bullets);
  }
}

const out = [];
for (const g of groups.values()) {
  const row = {
    reportTitle: g.reportTitle,
    programLine: g.programLine,
    reporter:    g.reporter,
    weekEnding:  WEEK_ENDING
  };
  for (const f of FIELDS) {
    const deduped = dedup(g.bullets[f]);
    row[f] = deduped.length ? deduped.join('\n') : 'N/A';
  }
  out.push({ json: row });
}

console.log('[Summarize] reporters:', out.map(i => i.json.reporter).join(', '));
return out;

