function parseIfString(val) {
  if (!val) return {};
  if (typeof val === 'object' && !Array.isArray(val)) return val;
  let s = String(val).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(s); } catch {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch {} }
  return {};
}

function splitAndClean(text) {
  if (!text || String(text).trim().toLowerCase() === 'n/a') return 'N/A';

  const raw = String(text).replace(/\r/g, '');

  // Split on newline OR on an inline bullet char that follows a word boundary
  // This catches both "\n• item" and "sentence,• item" patterns
  const lines = raw
    .split(/\n|(?<=\S)\s*[•·\u2022]\s*/)
    .map(l => l.replace(/^[\s•·\u2022\-\*,]+/, '').trim())
    .filter(l => l.length > 0 && l.toLowerCase() !== 'n/a');

  return lines.length ? lines.join('\n') : 'N/A';
}

for (const item of items) {
