  `;

  const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  // Use sections[] built by Format Table node
  const rows = (report.sections || []).map(section => {
    const raw = String(section.content ?? 'N/A');
    let cellHtml;

    if (raw.trim().toLowerCase() === 'n/a') {
      cellHtml = 'N/A';
    } else {
      const lines = raw.split('\n')
        .map(l => l.replace(/^[\s•·\u2022\-\*]+/, '').trim())
        .filter(l => l && l.toLowerCase() !== 'n/a' && !isMetaNote(l));

      cellHtml = lines.length
        ? '<ul>' + lines.map(l => `<li>${esc(l)}</li>`).join('') + '</ul>'
        : 'N/A';
    }

    return `<tr>
      <td class="row-label">${esc(section.label).replace(/\n/g,'<br>')}</td>
      <td class="row-content">${cellHtml}</td>
    </tr>`;
  }).join('');

  return `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><style>${CSS}</style></head>
<body>
  <h1>${esc(report.reportTitle)}</h1>
  <p class="subtitle">${esc(report.programLine)}</p>
  <hr class="divider">
  <p class="info"><span class="label">Name: </span>${esc(report.reporter)}</p>
  <p class="info"><span class="label">Week Ending: </span>${esc(report.weekEnding)}</p>
  <hr class="divider">
  <table>${rows}</table>
</body>
</html>`;
}

