const results = [];

for (const inputItem of items) {
  const reporter = (inputItem.json?.reporter || '').trim();
  const reporterNorm = reporter.toLowerCase();

  // Skip N/A reporters — these are unassigned tickets, do not generate a report
  if (EXCLUDED.includes(reporterNorm)) {
    console.log(`[Prepare Email Attachment] Skipping N/A reporter item`);
    continue;
  }

  const inputBinary = inputItem.binary || {};

  // DocRaptor returns PDF binary under key "data" — NOT "data.data"
  const pdfBinary = inputBinary.data || inputBinary.attachment || null;

  const weekEnding = inputItem.json?.weekEnding
    || new Date().toISOString().split('T')[0];

  const fileName = `Weekly_Report_${reporter.replace(/\s+/g, '_')}_${weekEnding}.pdf`;

  if (!pdfBinary) {
    console.error(`[Prepare Email Attachment] No binary for reporter: ${reporter}`);
  }

  results.push({
    json: {
      fileName,
      weekEnding,
      reporter,
      emailSubject: `Weekly Status Report - ${weekEnding}`,
      emailReady: !!pdfBinary
    },
    binary: pdfBinary ? {
      attachment: {
        data: pdfBinary.data,
        mimeType: 'application/pdf',
        fileName
      }
    } : {}
  });
}

return results;

// ─────────────────────────────────────────────────────────────────────
// Collect All PDFs — REPLACES Aggregate1 + Loop Over Items
//
// All reporter items arrive here in parallel after Prepare Email Attachment.
// We wait for ALL items (n8n delivers the full batch) then bundle them
// into a single email item with all PDFs as named attachments.
//
// This is the core fix: no loop, no premature Done-branch firing.
// ─────────────────────────────────────────────────────────────────────

const allItems = items; // all parallel items arrive together

const attachments = {};
const reporters = [];
const failedReporters = [];

const weekEnding = allItems[0]?.json?.weekEnding
  || new Date().toISOString().split('T')[0];

allItems.forEach((item, index) => {
  const reporter = item.json?.reporter || `Reporter_${index + 1}`;
  const fileName = item.json?.fileName
    || `Weekly_Report_${reporter.replace(/\s+/g, '_')}_${weekEnding}.pdf`;

  const binaryData = item.binary?.attachment?.data;

  if (binaryData) {
    attachments[`attachment${index}`] = {
      data: binaryData,
      mimeType: 'application/pdf',
      fileName
    };
    reporters.push(reporter);
  } else {
    failedReporters.push(reporter);
    console.error(`[Collect All PDFs] Missing binary for: ${reporter}`);
  }
});

const reportCount = reporters.length;
const totalExpected = allItems.length;

console.log(`[Collect All PDFs] ${reportCount}/${totalExpected} PDFs collected. Reporters: ${reporters.join(', ')}`);
if (failedReporters.length) {
  console.warn(`[Collect All PDFs] Missing PDFs for: ${failedReporters.join(', ')}`);
}

return [{
  json: {
    weekEnding,
    reporters: reporters.join(', '),
    failedReporters: failedReporters.join(', ') || 'None',
    reportCount,
    totalExpected,
    emailSubject: `Weekly Status Reports - Week Ending ${weekEnding}`,
    emailReady: reportCount > 0
  },
  binary: attachments
}];
